import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {SliderComponent} from "./slider.component";
import {PI_SLIDER_ACTION, PI_SLIDER_CARD} from "./slider.types";

export * from "./slider.types";

registerCardComponent({
  name: PI_SLIDER_CARD,
  component: SliderComponent,
  events: actionTypesToEvents(PI_SLIDER_ACTION),
});

import React, {useEffect, useRef, useState} from "react";
import {type PiCardProps} from "@pihanga2/core";
import {Slider as SliderUI} from "@/components/ui/slider";
import {useFormContext} from "@/cards/form/form.context";
import {cn} from "@/lib/utils";
import type {PiSliderEvents, PiSliderProps} from "./slider.types";

export const SliderComponent = (
  props: PiCardProps<PiSliderProps, PiSliderEvents>,
): React.ReactNode => {
  const {
    name,
    value: propValue,
    defaultValue,
    selfManaged = false,
    min = 0,
    max = 100,
    step = 1,
    disabled,
    debounceMs = 0,
    suppressChangedEvents = false,
    label,
    showTicks = false,
    tickStep,
    majorTickStep,
    suppressTickLabels = false,
    tickLabels,
    className,
    cardName,
    onChanged,
    onCommitted,
  } = props;

  // Detect if we are inside a pi/form card via React context.
  const form = useFormContext();
  const useFormData = form.isInForm && Boolean(name);

  // Internal state used only when selfManaged=true and not bound to a form.
  const [managedValue, setManagedValue] = useState<number>(
    defaultValue ?? propValue ?? min,
  );

  // The "canonical" value from props / form / self-managed state.
  const canonicalValue = useFormData
    ? ((form.formData[name!] as number | undefined) ?? min)
    : selfManaged
      ? managedValue
      : (propValue ?? min);

  // Keep a ref to the latest canonical value so event handlers always see
  // the most up-to-date external value even if it changed during a drag.
  const canonicalValueRef = useRef(canonicalValue);
  canonicalValueRef.current = canonicalValue;

  // "Interactive" drag state — tracks knob position independently while the
  // user is actively dragging so we don't need an external value round-trip.
  const isDragging = useRef(false);
  const [interactiveValue, setInteractiveValue] =
    useState<number>(canonicalValue);

  // While dragging the knob follows pointer; otherwise it reflects the canonical value.
  const displayValue = isDragging.current ? interactiveValue : canonicalValue;

  // Refs for debounce: timer handle + latest pending value.
  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingValue = useRef<number>(canonicalValue);

  // Clean up any pending debounce timer on unmount.
  useEffect(() => {
    return () => {
      if (debounceTimer.current != null) clearTimeout(debounceTimer.current);
    };
  }, []);

  function dispatchChanged(newValue: number) {
    // Silently skip if the caller has opted out of continuous change events.
    if (suppressChangedEvents) return;

    if (useFormData) {
      form.handleChange(name!, newValue);
    } else {
      onChanged({name, value: newValue});
    }
  }

  // Called on pointer/touch down — enter interactive mode so the knob can
  // move freely without waiting for an external state update.
  function handlePointerDown() {
    isDragging.current = true;
    setInteractiveValue(canonicalValueRef.current);
  }

  function handleValueChange(newValues: number[]) {
    const newValue = newValues[0] ?? min;

    // Guard: only update interactive display when actively dragging.
    if (!isDragging.current) return;

    setInteractiveValue(newValue);

    // Update internal state immediately so the thumb moves without lag.
    if (selfManaged && !useFormData) {
      setManagedValue(newValue);
    }

    if (debounceMs > 0) {
      // Record the latest value and (re)start the quiet-window timer.
      pendingValue.current = newValue;
      if (debounceTimer.current != null) clearTimeout(debounceTimer.current);
      debounceTimer.current = setTimeout(() => {
        debounceTimer.current = null;
        dispatchChanged(pendingValue.current);
      }, debounceMs);
    } else {
      dispatchChanged(newValue);
    }
  }

  function handleValueCommit(newValues: number[]) {
    const newValue = newValues[0] ?? min;

    // Leave interactive mode — on next render displayValue reverts to canonicalValue,
    // snapping the knob back to whatever the external state currently says.
    isDragging.current = false;
    setInteractiveValue(canonicalValueRef.current);

    // Cancel any pending debounced onChanged — the committed event supersedes it.
    if (debounceTimer.current != null) {
      clearTimeout(debounceTimer.current);
      debounceTimer.current = null;
    }

    // When debounce is active (and not suppressed), flush the final value via
    // onChanged before the committed event so listeners always see both.
    if (debounceMs > 0 && !suppressChangedEvents) {
      dispatchChanged(newValue);
    }

    onCommitted({name, value: newValue});
  }

  // --- Tick calculations ---
  // tickStep=0  → hide minor ticks only  (major still shown if majorTickStep > 0)
  // majorTickStep=0 → hide major ticks only (minor still shown if tickStep > 0)
  // Both 0 → nothing shown
  const effectiveMinorStep = tickStep !== undefined ? tickStep : step;
  const showMinorTicks = effectiveMinorStep > 0;

  // Auto major step: use minor step as base when minor ticks are on;
  // fall back to `step` when minor ticks are off (tickStep=0) so that
  // major ticks can still be auto-calculated from the slider's step.
  const autoMajorBase = showMinorTicks ? effectiveMinorStep : step;
  const autoMajorStep =
    autoMajorBase > 0
      ? Math.max(
          autoMajorBase,
          Math.round((max - min) / 5 / autoMajorBase) * autoMajorBase,
        )
      : 0;
  // majorTickStep undefined → auto; 0 → no major ticks; >0 → explicit value
  const resolvedMajorStep =
    majorTickStep !== undefined ? majorTickStep : autoMajorStep;
  const showMajorTicks = resolvedMajorStep > 0;

  const renderTicks = showTicks && (showMinorTicks || showMajorTicks);

  // Use minor spacing as base when available; fall back to major spacing.
  const baseStep = showMinorTicks ? effectiveMinorStep : resolvedMajorStep;
  const ticks = renderTicks
    ? Array.from(
        {length: Math.round((max - min) / baseStep) + 1},
        (_, i) => min + i * baseStep,
      )
    : [];

  return (
    <div
      data-pihanga={cardName}
      className={cn("flex flex-col gap-2", className)}
    >
      {label && (
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium leading-none">{label}</span>
          <span className="text-sm text-muted-foreground tabular-nums">
            {displayValue}
          </span>
        </div>
      )}
      <SliderUI
        value={[displayValue]}
        min={min}
        max={max}
        step={step}
        disabled={disabled}
        onPointerDown={handlePointerDown}
        onValueChange={handleValueChange}
        onValueCommit={handleValueCommit}
        className="w-full"
      />
      {renderTicks && (
        <div
          aria-hidden="true"
          className="flex w-full items-baseline justify-between px-0.5"
        >
          {ticks.map((tick) => {
            const isMajor =
              showMajorTicks && (tick - min) % resolvedMajorStep === 0;
            const isActive = tick <= displayValue;
            // Show label when:
            //  • suppressTickLabels is false, AND
            //  • tick is major  OR  there are no major ticks (label every minor tick)
            const showLabel =
              !suppressTickLabels && (isMajor || !showMajorTicks);
            const labelText = showLabel
              ? tickLabels && tick in tickLabels
                ? tickLabels[tick]
                : String(tick)
              : "";

            return (
              <div key={tick} className="flex flex-col items-center gap-1">
                <div
                  className={cn(
                    "w-0.5 rounded-full transition-all duration-300",
                    isActive ? "bg-primary" : "bg-primary/20",
                    isMajor ? "h-3" : "h-1.5",
                  )}
                />
                <span
                  className={cn(
                    "text-xs font-medium transition-colors",
                    showLabel
                      ? "text-muted-foreground opacity-100"
                      : "opacity-0",
                  )}
                >
                  {labelText}
                </span>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const PI_SLIDER_CARD = "shad/slider";

export const Slider = createCardDeclaration<PiSliderProps, PiSliderEvents>(
  PI_SLIDER_CARD,
);

export const PI_SLIDER_ACTION = registerActions(PI_SLIDER_CARD, [
  "changed",
  "committed",
]);

export const onSliderChanged = createOnAction<PiSliderChangedEvent>(
  PI_SLIDER_ACTION.CHANGED,
);

/** @deprecated Use `onSliderChanged` instead. */
export const onPiSliderChanged = onSliderChanged;

/**
 * Fired once when the user **finishes** dragging (mouse-up / touch-end).
 *
 * Use this instead of `onSliderChanged` when you only care about the final
 * settled value and do not want to process every intermediate drag position.
 */
export const onSliderCommitted = createOnAction<PiSliderCommittedEvent>(
  PI_SLIDER_ACTION.COMMITTED,
);

/** @deprecated Use `onSliderCommitted` instead. */
export const onPiSliderCommitted = onSliderCommitted;

// ---------------------------------------------------------------------------
// Props & Events
// ---------------------------------------------------------------------------

export type PiSliderProps = {
  /**
   * Field name used to bind to FormContext when inside a pi/form card.
   * When provided the component reads its value from form data and writes
   * back via form.handleChange.
   */
  name?: string;

  /**
   * Controlled numeric value (single thumb).
   * Ignored when `name` is set and the component is inside a pi/form,
   * and also ignored when `selfManaged` is true (use `defaultValue` instead).
   */
  value?: number;

  /**
   * Initial value used when `selfManaged` is true.
   * Falls back to `value` → `min` → 0 if not provided.
   */
  defaultValue?: number;

  /**
   * When true the slider keeps its own internal value state.
   * Dragging updates the displayed value immediately without needing an
   * external state update.  `onChanged` is still fired on every change so
   * the app can react (or log) without being responsible for feeding the
   * value back as a prop.
   *
   * Ignored when inside a pi/form (form state takes precedence).
   */
  selfManaged?: boolean;

  /** Minimum value of the slider range. Defaults to 0. */
  min?: number;

  /** Maximum value of the slider range. Defaults to 100. */
  max?: number;

  /** Stepping interval between selectable values. Defaults to 1. */
  step?: number;

  /** When true, the slider is disabled and non-interactive. */
  disabled?: boolean;

  /**
   * Debounce delay in milliseconds applied to `onChanged` during continuous
   * drag.  Only the last value within each quiet window is dispatched.
   *
   * Useful when the `onChanged` handler is expensive (e.g. triggers an API
   * call) — set e.g. `debounceMs: 200` to cap the event rate.
   *
   * Has no effect on `onCommitted`, which always fires exactly once at
   * drag-end regardless of this setting.
   *
   * Omit (or set to 0) to dispatch on every drag position (default behaviour).
   */
  debounceMs?: number;

  /**
   * When true, `onSliderChanged` is **never** dispatched during drag.
   *
   * Use this together with `onSliderCommitted` when you only care about
   * the final settled value and want to eliminate all intermediate Redux
   * actions entirely (stricter than `debounceMs`).
   *
   * `onSliderCommitted` is unaffected and always fires on release.
   * `selfManaged` visual updates are also unaffected.
   */
  suppressChangedEvents?: boolean;

  /**
   * Optional label text rendered above the slider.
   * When provided, the current numeric value is shown to the right of the label.
   */
  label?: string;

  /**
   * When true, tick marks are rendered below the slider track.
   */
  showTicks?: boolean;

  /**
   * Spacing between consecutive **minor** tick marks in value units.
   * Defaults to `step`.
   * Set to `0` to hide minor ticks only — major ticks are still shown
   * if `majorTickStep` is non-zero.
   */
  tickStep?: number;

  /**
   * Interval (in value units) between **major** (tall, labelled) ticks.
   * Defaults to `(max - min) / 5` rounded to the nearest `tickStep`.
   * Set to `0` to hide major ticks only — minor ticks are still shown
   * if `tickStep` is non-zero.
   */
  majorTickStep?: number;

  /**
   * When true, no tick labels are rendered at all (only the tick marks).
   * Overrides `tickLabels` and the default numeric labels.
   */
  suppressTickLabels?: boolean;

  /**
   * Custom labels keyed by value.  When provided for a value, the custom
   * string is shown instead of the numeric value.  Pass `""` to suppress the
   * label for a specific tick.
   *
   * @example { 0: "Min", 50: "Mid", 100: "Max" }
   */
  tickLabels?: Record<number, string>;

  /** Extra Tailwind / CSS classes forwarded to the root wrapper element. */
  className?: string;
};

export type PiSliderChangedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** New numeric value after the change. */
  value: number;
};

export type PiSliderCommittedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** Final settled value when the user released the thumb. */
  value: number;
};

export type PiSliderEvents = {
  onChanged: PiSliderChangedEvent;
  onCommitted: PiSliderCommittedEvent;
};
